const app=document.querySelector('#app');
let completed=[];try{completed=JSON.parse(localStorage.getItem('aily-completed')||'[]');if(!Array.isArray(completed))completed=[]}catch{}
function save(){try{localStorage.setItem('aily-completed',JSON.stringify(completed))}catch{}}
const topics=[
['Variables & types','Python stores values with types. Integers count things; floats represent measurements; booleans represent conditions. None represents an absent value.','age = 21\nscore = 0.92\nis_ready = score >= 0.8\nlabel = None\nprint(type(score).__name__)','What does the example print?','float'],
['Collections & slicing','Lists hold ordered values. Dictionaries connect keys to values. Tuples are immutable sequences; sets hold unique values. Python indexes from zero, and a slice excludes its end position.','scores = [72, 85, 91, 68]\nstudent = {"name": "Sam", "score": 85}\nprint(scores[1:3])\nprint(student["name"])','Select the last two scores.','scores[-2:] returns [91, 68].'],
['Conditions & loops','Use conditions to branch and loops to process items. Indentation defines the body of each block. Use enumerate when you need both an index and its value.','scores = [72, 85, 91]\nfor index, score in enumerate(scores):\n    if score >= 80:\n        print(index, "ready")','Which indexes are printed?','1 and 2. Both corresponding scores are at least 80.'],
['Functions & scope','Functions bundle a task into a reusable operation. Return sends a result back to the caller; print only displays it. Variables created inside a function are generally local to it.','def normalize(value, maximum=100):\n    return value / maximum\n\nscaled = normalize(75)\nprint(scaled)','What is normalize(6, maximum=10)?','0.6. The supplied maximum replaces the default.'],
['Comprehensions','A comprehension builds a collection from an iterable. Keep it simple: readable code is more useful than a clever one-liner.','scores = [72, 85, 91, 68]\npassed = [s for s in scores if s >= 80]\nsquared = {n: n ** 2 for n in range(3)}','What is passed?','[85, 91]'],
['Imports & environments','Import modules to reuse code. pip installs packages. A virtual environment isolates a project’s dependencies so different projects can use different versions. Run these setup commands in a terminal.','python -m venv .venv\n# Windows PowerShell:\n.venv\\Scripts\\Activate.ps1\n# macOS / Linux: source .venv/bin/activate\npython -m pip install numpy pandas matplotlib','How would you import NumPy using its usual alias?','import numpy as np'],
['Files & tracebacks','Use with to close files reliably. CSV stores tabular text; JSON stores structured values. When an exception appears, read the final line for its type and message, then locate your code in the traceback.','import json\n\nwith open("profile.json", encoding="utf-8") as file:\n    profile = json.load(file)\n\nprint(profile.get("name", "Unknown"))','What does FileNotFoundError usually tell you?','The file is not at the specified path. Check the filename and current working directory.'],
['NumPy: arrays & shapes','An array is a grid of values. Shape tells you the size along each axis. For a table shaped (3, 2), axis 0 runs through the rows, and axis 1 through the columns. Vectorised operations act on whole arrays.','import numpy as np\n\nx = np.array([[1, 2], [3, 4], [5, 6]])\nprint(x.shape)       # (3, 2)\nprint(x.mean(axis=0)) # [3. 4.]\nprint(x * 2)\nprint(x + np.array([10, 20]))','Why can a shape (2,) array be added to x?','Broadcasting aligns trailing dimensions. The two values are added to the two columns of every row. Dimensions must match or one must equal 1.'],
['pandas: working with tables','A DataFrame stores named columns. Inspect before transforming: head shows sample rows, info shows types and missing values, and describe summarises numeric columns. Handle missing values deliberately.','import pandas as pd\n\ndf = pd.DataFrame({\n    "hours": [2, 4, None, 6],\n    "score": [55, 70, 65, 90]\n})\nprint(df.head())\nclean = df.dropna(subset=["hours"])\nprint(clean.loc[clean["score"] >= 70, ["hours", "score"]])','How many rows remain in clean?','3. The row with missing hours was removed. Dropping rows is not always appropriate; investigate why data is missing.'],
['Plotting & interpretation','Scatter plots compare two numeric variables. Histograms show distributions. Line plots show ordered change, often over time. Always label axes; a visible association does not establish causation.','import matplotlib.pyplot as plt\n\nhours = [2, 4, 6]\nscores = [55, 70, 90]\nplt.scatter(hours, scores)\nplt.xlabel("Study hours")\nplt.ylabel("Assessment score")\nplt.show()','Which plot would show the distribution of 200 assessment scores?','A histogram, using plt.hist(scores).']
];
const chapters=[{id:'foundations',title:'Meet machine learning',desc:'From examples to predictions. Understand what a model actually learns.',icon:'✦',tag:'START HERE',time:'12 min',lessons:[['A model learns a pattern','Machine learning fits patterns from examples instead of requiring a separate rule for every case. A spam classifier learns from messages labelled spam or not spam. Its predictions are estimates, not guarantees.'],['Features and labels','Features are the inputs available when making a prediction. The label is the outcome you want to predict. To estimate house prices, area and location could be features and sale price the label. An identifier is not automatically a useful feature.'],['Training versus inference','Training adjusts a model using examples. Inference applies that fitted model to a new input. A trained model does not automatically learn from every new request; updating it requires a deliberate learning process.']],q:'For a model predicting house prices, which is the label?',options:['Floor area','Sale price','Number of rooms'],correct:1,why:'Sale price is the target you want to predict. Area and room count are possible input features.'},
{id:'problems',title:'Think in problems',desc:'Classification, regression, and clustering. Learn to tell them apart.',icon:'⊞',tag:'FOUNDATIONS',time:'15 min',lessons:[['Classification','Classification predicts a category: spam or not spam, a plant species, or whether a transaction is suspicious. Many classifiers estimate probabilities before a threshold or selection rule converts them into a class.'],['Regression','Regression predicts a numeric quantity such as temperature or delivery time. A linear model is often a useful baseline. More complexity is justified by evaluation, not by a model sounding advanced.'],['Clustering','Clustering groups similar examples without predefined target labels. The groups depend on your features, scaling, distance measure, and algorithm. A discovered group is not necessarily a meaningful real-world category.']],q:'Predicting a delivery duration in minutes is usually…',options:['Classification','Clustering','Regression'],correct:2,why:'Minutes are a numeric quantity. If you instead predicted late versus on time, that would be classification.'},
{id:'evaluation',title:'Beyond a good score',desc:'Find out whether your model works on examples it has never seen.',icon:'↗',tag:'MODEL THINKING',time:'18 min',lessons:[['Hold out unseen data','Use training data to fit, validation data to choose settings, and a final test set to estimate performance after those choices. Split in a way that resembles deployment: future prediction usually needs a time-based split.'],['Overfitting and baselines','An overfit model captures training noise and fails to generalise. Compare against simple baselines. For regression, predicting the training-set mean can be a baseline; for classification, the most frequent training class can be one.'],['Metrics and leakage','Accuracy alone can hide poor detection of rare events. Precision asks how many predicted positives are truly positive; recall asks how many actual positives are found. Leakage occurs when evaluation uses information unavailable in real prediction. Fit preprocessing only on training data.']],q:'A model scores 99% on training data and 61% on representative unseen data. What should you investigate?',options:['Possible overfitting or a data mismatch','Whether training accuracy can reach 100%','Only the colour of the chart'],correct:0,why:'A large gap suggests poor generalisation. Investigate overfitting, data quality, and differences between training and test distributions.'}];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function network(){return `<svg class="network" viewBox="0 0 360 220" aria-label="Connected layers of a neural network" role="img"><g stroke="#665a8c" stroke-width="1">${[45,110,175].map(y=>[25,80,140,195].map(z=>`<line x1="65" y1="${y}" x2="180" y2="${z}"/>`).join('')).join('')}${[25,80,140,195].map(y=>[70,150].map(z=>`<line x1="180" y1="${y}" x2="295" y2="${z}"/>`).join('')).join('')}</g>${[45,110,175].map(y=>`<circle cx="65" cy="${y}" r="14" fill="#9380d4"/>`).join('')}${[25,80,140,195].map(y=>`<circle cx="180" cy="${y}" r="17" fill="#c5b3ff"/>`).join('')}${[70,150].map(y=>`<circle cx="295" cy="${y}" r="19" fill="#dbf4bc"/>`).join('')}<text x="48" y="219" fill="#a99ec3" font-size="10" letter-spacing="2">INPUT</text><text x="159" y="219" fill="#a99ec3" font-size="10" letter-spacing="2">LEARN</text><text x="271" y="219" fill="#a99ec3" font-size="10" letter-spacing="2">PREDICT</text></svg>`}
function chapterCards(){return chapters.map((c,i)=>`<a class="card" href="#chapter/${c.id}"><div class="card-top"><span class="icon ${i===1?'green':i===2?'orange':''}">${c.icon}</span><span class="pill">${completed.includes(c.id)?'COMPLETED':c.tag}</span></div><h3>${c.title}</h3><p>${c.desc}</p><div class="card-bottom"><span>Chapter 0${i+1} · ${c.time}</span><span>Explore ↗</span></div></a>`).join('')}
function home(){app.innerHTML=`<h1>A little more curious today?</h1><p>Big ideas, small steps. Let’s make AI click.</p><section class="hero"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>You know Python.<br>Now, think in possibilities.</h2><p>Discover how machines learn, one clear concept and hands-on experiment at a time.</p><a class="button" href="#chapter/${chapters.find(c=>!completed.includes(c.id))?.id||'foundations'}">${completed.length?'Continue learning':'Begin your journey'} <span>→</span></a></div>${network()}</section><div class="stats"><div class="stat"><span class="icon">▤</span><div><strong>${chapters.filter(c=>completed.includes(c.id)).length} <span style="color:#b3b4c0;font-size:15px">/ 3</span></strong><small>Chapters completed</small></div></div><div class="stat"><span class="icon green">◉</span><div><strong>2</strong><small>Experiments to explore</small></div></div><div class="stat"><span class="icon orange">⚑</span><div><strong>5</strong><small>Real-world challenges</small></div></div></div><div class="section-title"><h2>Your learning path</h2><a href="#learn">View learning path ↗</a></div><div class="cards">${chapterCards()}</div><div class="two-col"><div><div class="section-title"><h2>Less reading. More doing.</h2></div><section class="arcade-banner"><div class="arcade-art" aria-hidden="true">⌁</div><div><span class="eyebrow" style="color:#7c6aae">THE AI ARCADE</span><h3>Play with the possibilities.</h3><p>Move a slider. Watch a model change.<br>See the idea for yourself.</p><a href="#arcade" class="button secondary">Enter the arcade ↗</a></div></section></div><div><div class="section-title"><h2>A thought to get you started</h2></div><section class="daily"><span class="eyebrow" style="color:#a08549">PUT YOUR INTUITION TO WORK</span><p>A model memorises every training example. Does that make it a good model?</p><a href="#challenges" style="color:var(--purple);font-size:14px">Let’s think it through →</a></section></div></div>`}
function learn(){app.innerHTML=`<h1>Your learning path</h1><p>Start with the essentials. Build up to making your own model decisions.</p><a class="arcade-banner" href="#python"><span class="icon">⌘</span><div><h3>First, a little Python refresh.</h3><p>Ten focused topics. One useful reference. Check your readiness before you begin.</p></div><span>→</span></a><div class="section-title"><h2>01 — Foundations of machine learning</h2><span class="note">3 chapters</span></div><div class="cards">${chapterCards()}</div><div class="lesson" style="margin-top:25px"><h2>Learn it. Try it. Apply it.</h2><p>After each chapter, head to the arcade to experiment, then use the Challenge Lab to practise choosing an approach. Your completed chapters are saved in this browser.</p><a class="button secondary" href="#challenges">Open Challenge Lab →</a></div>`}
function quiz(q,opts,correct,why,id){return `<div class="quiz"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>${q}</h3><div class="choices">${opts.map((o,i)=>`<button class="choice" data-quiz="${id}" data-answer="${i}">${o}</button>`).join('')}</div><div class="feedback" id="feedback-${id}" aria-live="polite"></div></div>`}
function wireQuiz(id,correct,why,onCorrect){document.querySelectorAll(`[data-quiz="${id}"]`).forEach(b=>b.onclick=()=>{document.querySelectorAll(`[data-quiz="${id}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');const ok=+b.dataset.answer===correct;document.getElementById('feedback-'+id).textContent=(ok?'That’s right. ':'Take another look. ')+why;if(ok&&onCorrect)onCorrect()})}
function python(){app.innerHTML=`<h1>Python essentials</h1><p>The Python you need for ML, all in one place. Refresh a topic or check your readiness.</p><p class="note">Examples are for your own Python environment. Expand each exercise to check your answer.</p>${quiz('Which expression gives the number of rows in a pandas DataFrame df?',['df.shape[0]','df.shape[1]','df.columns'],0,'Shape is (rows, columns), so index 0 gives the row count.','python')}<div class="lesson-layout"><div class="topic-nav">${topics.map((t,i)=>`<a href="#python" data-scroll="topic-${i}">${String(i+1).padStart(2,'0')} &nbsp;${t[0]}</a>`).join('')}<a href="#python" data-scroll="mini-task">11 &nbsp;Put it together</a></div><div>${topics.map((t,i)=>`<section class="lesson" id="topic-${i}"><span class="eyebrow" style="color:var(--purple)">PYTHON / ${String(i+1).padStart(2,'0')}</span><h2>${t[0]}</h2><p>${t[1]}</p><pre><code>${esc(t[2])}</code></pre><div class="exercise"><strong>Your turn</strong><p>${t[3]}</p><details><summary>Check the answer</summary><p>${esc(t[4])}</p></details></div></section>`).join('')}<section class="lesson" id="mini-task"><h2>Put it together</h2><p>Create the table below. Inspect its shape, remove rows with missing study hours, keep scores of at least 70, and plot study hours against scores.</p><pre>hours,score\n2,55\n4,70\n,65\n6,90\n8,85</pre><details><summary>See one solution</summary><pre>${esc('import pandas as pd\nimport matplotlib.pyplot as plt\nfrom io import StringIO\n\ncsv = "hours,score\\n2,55\\n4,70\\n,65\\n6,90\\n8,85"\ndf = pd.read_csv(StringIO(csv))\nprint(df.shape)  # (5, 2)\nclean = df.dropna(subset=["hours"])\nselected = clean.loc[clean["score"] >= 70]\nplt.scatter(selected["hours"], selected["score"])\nplt.xlabel("Study hours")\nplt.ylabel("Assessment score")\nplt.show()')}</pre></details><p>Ready? Move from manipulating data to learning from it.</p><a class="button" href="#chapter/foundations">Start AI foundations →</a></section></div></div>`;wireQuiz('python',0,'Shape is (rows, columns), so index 0 gives the row count.');document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})})}
function chapter(id){const c=chapters.find(c=>c.id===id);if(!c){location.hash='learn';return}app.innerHTML=`<a href="#learn" class="note">← Learning path</a><h1 style="margin-top:20px">${c.title}</h1><p>${c.desc}</p>${c.lessons.map((l,i)=>`<section class="lesson"><span class="eyebrow" style="color:var(--purple)">CONCEPT 0${i+1}</span><h2>${l[0]}</h2><p>${l[1]}</p></section>`).join('')}${quiz(c.q,c.options,c.correct,c.why,c.id)}<div id="chapter-done">${completed.includes(id)?'<p>✓ Chapter completed. Try applying it in the arcade.</p><a class="button" href="#arcade">Explore the arcade →</a>':'<p class="note">Answer the checkpoint correctly to complete this chapter.</p>'}</div>`;wireQuiz(c.id,c.correct,c.why,()=>{if(!completed.includes(id)){completed.push(id);save()}document.getElementById('chapter-done').innerHTML='<p>✓ Chapter completed. Your progress is saved in this browser.</p><a class="button" href="#learn">Back to learning path →</a>'})}
function arcade(){app.innerHTML=`<h1>The AI arcade</h1><p>A safe space to experiment, break assumptions, and make things click.</p><div class="cards"><a class="card" href="#experiment/boundary"><span class="icon">⊹</span><h3>Draw the boundary</h3><p>Move a decision boundary and see which points your classifier gets right.</p><div class="card-bottom"><span>CLASSIFICATION · 5 MIN</span><span>Play →</span></div></a><a class="card" href="#experiment/overfit"><span class="icon green">⌁</span><h3>The overfitting playground</h3><p>Change model complexity. Discover why a closer fit is not always better.</p><div class="card-bottom"><span>GENERALISATION · 5 MIN</span><span>Play →</span></div></a></div>`}
const pts=Array.from({length:32},(_,i)=>({x:35+(i*73%460),y:35+(i*107%240),c:(35+(i*73%460)+.5*(35+(i*107%240))>340)?1:0}));
function experiment(id){const boundary=id==='boundary';app.innerHTML=`<a href="#arcade" class="note">← AI arcade</a><h1 style="margin-top:20px">${boundary?'Draw the boundary':'The overfitting playground'}</h1><p>${boundary?'Adjust the line to separate the two classes. Purple circles and mint squares are the true labels.':'Compare a curve with noisy observations and the underlying signal that generated them.'}</p><div class="lab"><svg id="plot" class="plot" viewBox="0 0 540 330" role="img" aria-label="Interactive model plot"></svg><div class="controls">${boundary?'<label for="intercept">Boundary position <output id="iv"></output></label><input id="intercept" type="range" min="50" max="520" value="240"><label for="slope">Boundary tilt <output id="sv"></output></label><input id="slope" type="range" min="-1" max="1" step="0.05" value="0">':'<label for="complexity">Model flexibility <output id="cv"></output></label><input id="complexity" type="range" min="0" max="100" value="20">'}<div class="feedback" id="result" aria-live="polite"></div><p>${boundary?'Points to the right of the boundary are predicted mint. Outlined points are mistakes. This is training accuracy on a tiny toy dataset, not evidence of real-world performance.':'Purple: candidate curve. Mint dashed: true signal. Dots: noisy training observations. This is a constructed illustration, not an actual trained model.'}</p><button class="button secondary" id="reset">Reset experiment</button></div></div><section class="lesson" style="margin-top:22px"><h2>Try this</h2><p>${boundary?'First move the position slider. Can a vertical line separate every point? Now change the tilt. Consider how a more flexible boundary might help—and why you would still need unseen test data.':'Move flexibility from low to high. The most flexible curve passes through all the training observations, including their noise. Notice whether it gets closer to the true signal everywhere.'}</p><a href="#chapter/evaluation" style="color:var(--purple)">Understand model evaluation →</a></section>`;const draw=()=>{let s='<g stroke="#e9eaf3">'+[60,120,180,240,300].map(y=>`<path d="M25 ${y}H515"/>`).join('')+'</g>';if(boundary){const b=+document.getElementById('intercept').value,m=+document.getElementById('slope').value;let correct=0;s+=`<path d="M${b} 0 L${b+m*330} 330" stroke="#9a86e9" stroke-width="2" stroke-dasharray="6 5"/>`;for(const p of pts){const ok=+(p.x>b+m*p.y)===p.c;if(ok)correct++;s+=p.c?`<rect x="${p.x-6}" y="${p.y-6}" width="12" height="12" rx="3" fill="#6cba9c" ${ok?'':'stroke="#302449" stroke-width="2"'}/>`:`<circle cx="${p.x}" cy="${p.y}" r="6" fill="#8b6ee5" ${ok?'':'stroke="#302449" stroke-width="2"'}/>`}document.getElementById('iv').textContent=b;document.getElementById('sv').textContent=m;document.getElementById('result').textContent=`${correct} / ${pts.length} correct · ${Math.round(correct/pts.length*100)}% training accuracy`;}else{const f=+document.getElementById('complexity').value/100,truth=x=>160+65*Math.sin(x/100),data=Array.from({length:13},(_,i)=>({x:30+i*40,y:truth(30+i*40)+22*Math.sin(i*9+2)}));const pred=x=>{let j=Math.min(11,Math.max(0,Math.floor((x-30)/40)));const a=data[j],b=data[j+1],inter=a.y+(b.y-a.y)*(x-a.x)/40;return f<.5?(1-2*f)*160+2*f*truth(x):(2-2*f)*truth(x)+(2*f-1)*inter};let train=0,test=0;data.forEach(p=>train+=(pred(p.x)-p.y)**2);for(let x=30;x<=510;x+=4)test+=(pred(x)-truth(x))**2;for(const [fun,color,dash] of [[truth,'#6cba9c','6 5'],[pred,'#8b6ee5','']])s+=`<path d="${Array.from({length:121},(_,i)=>`${i?'L':'M'}${30+i*4} ${fun(30+i*4)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="3" stroke-dasharray="${dash}"/>`;data.forEach(p=>s+=`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#343047"/>`);document.getElementById('cv').textContent=Math.round(f*100)+'%';document.getElementById('result').textContent=`Training MSE: ${(train/13).toFixed(1)} · Error against true signal: ${(test/121).toFixed(1)}. ${f>.75?'The curve is fitting observation noise.':f<.25?'A flat curve misses the underlying pattern.':'The curve captures more of the signal.'}`;}document.getElementById('plot').innerHTML=s;};document.querySelectorAll('.controls input').forEach(x=>x.oninput=draw);document.getElementById('reset').onclick=()=>experiment(id);draw()}
const challenges=[['A shop wants to predict next month’s sales from historical monthly records. What is a sensible first step?',['Train the biggest neural network available','Use a seasonal or recent-sales baseline and evaluate on later months','Randomly shuffle months before every evaluation'],1,'Time order matters. Start with a forecasting baseline, hold out later periods, and ensure all features would be known at prediction time.'],['A medical screening dataset has 99% negative results. A model always predicts negative and gets 99% accuracy. What next?',['Declare it ready','Inspect recall, precision, and the costs of missed cases and false alarms','Increase the displayed decimal places'],1,'The model misses every positive case. Accuracy hides this. Evaluation and thresholds must reflect the task, with appropriate domain oversight.'],['You have customer purchase patterns but no predefined customer groups. Which approach is worth exploring?',['Clustering after checking and scaling the features','Regression against customer IDs','Classification without any target labels'],0,'Clustering can explore similarity. Its groups still need validation and interpretation; they are not automatically useful business segments.'],['A loan-default model uses a collections status recorded after default. What is the problem?',['Too few colours in the dashboard','Data leakage','The model needs more layers'],1,'The feature reveals information from after the outcome. Remove unavailable future information and evaluate using a realistic prediction cutoff.'],['A model memorises its training examples. What would make you trust it more?',['A perfect training score alone','Representative unseen evaluation and comparison with a simple baseline','A more impressive model name'],1,'Useful models generalise. Compare on data that reflects how the model will be used, without repeatedly tuning against the final test set.']];
function challengesPage(){app.innerHTML=`<h1>Challenge lab</h1><p>Think through the problem before reaching for a model. Each scenario explains the reasoning.</p>${challenges.map((c,i)=>quiz(c[0],c[1],c[2],c[3],'challenge'+i)).join('')}`;challenges.forEach((c,i)=>wireQuiz('challenge'+i,c[2],c[3]))}
const terms=[['Artificial intelligence','A broad field concerned with systems performing tasks associated with intelligence, such as perception, language, and decision-making.'],['Machine learning','Methods that fit patterns from data to support predictions, decisions, or exploration.'],['Feature','An input variable available to a model at prediction time.'],['Label','The target outcome supplied for an example in supervised learning.'],['Classification','Predicting a category or probabilities over categories.'],['Regression','Predicting a numeric quantity.'],['Clustering','Grouping examples by similarity without predefined target labels.'],['Linear regression','A baseline that models a numeric target as a weighted sum of inputs plus an intercept.'],['Logistic regression','A linear classification model that maps a score to class probabilities. Despite its name, it is used for classification.'],['Decision tree','A model that makes predictions through a sequence of feature-based splits. Deep trees can overfit.'],['Random forest','An ensemble of decision trees trained with randomness, combining predictions to reduce variance.'],['Neural network','A model built from layers of parameterised transformations. Training adjusts its parameters to reduce a loss.'],['Overfitting','Learning training-specific details or noise that do not generalise to new data.'],['Data leakage','Using information during training or evaluation that would not be available in the intended prediction setting.'],['Precision','True positives divided by all predicted positives. It measures how often positive predictions are correct.'],['Recall','True positives divided by all actual positives. It measures how many positive cases are found.'],['Embedding','A numeric vector representation whose relationships can encode useful similarities.'],['Inference','Applying a fitted model to an input to produce an output.']];
function atlas(){app.innerHTML=`<h1>AI atlas</h1><p>A small reference for the ideas and models you’ll meet along the way.</p><label for="search" class="note">Find a concept</label><input class="search" id="search" type="search" placeholder="Try overfitting, regression, or feature…"><div class="glossary" id="terms"></div>`;const render=()=>{const q=document.getElementById('search').value.toLowerCase(),list=terms.filter(t=>t.join(' ').toLowerCase().includes(q));document.getElementById('terms').innerHTML=list.length?list.map(t=>`<article class="card"><h3>${t[0]}</h3><p>${t[1]}</p></article>`).join(''):'<p class="empty">No matching concepts. Try a broader term.</p>'};document.getElementById('search').oninput=render;render()}
function route(){const hash=location.hash.slice(1)||'home',[page,id]=hash.split('/');const names={home:'Overview',learn:'Learning path',python:'Python essentials',arcade:'AI arcade',challenges:'Challenge lab',atlas:'AI atlas',chapter:'Learning path',experiment:'AI arcade'};document.getElementById('breadcrumb').innerHTML=`Your workspace <span>/ ${names[page]||'Overview'}</span>`;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(page==='chapter'?'learn':page==='experiment'?'arcade':page)));({home,learn,python,arcade,challenges:challengesPage,atlas,chapter:()=>chapter(id),experiment:()=>experiment(id)}[page]||home)();document.title=`${names[page]||'Overview'} — Aily`;window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_boundary_experiment',description:'Open the decision boundary experiment and set its position and tilt. Does not complete a lesson.',inputSchema:{type:'object',properties:{position:{type:'number',minimum:50,maximum:520},tilt:{type:'number',minimum:-1,maximum:1}},required:['position','tilt'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isFinite(input.position)||input.position<50||input.position>520||!Number.isFinite(input.tilt)||input.tilt < -1||input.tilt>1)throw new Error('Position must be 50–520 and tilt must be -1–1.');history.replaceState(null,'','#experiment/boundary');route();document.getElementById('intercept').value=input.position;document.getElementById('slope').value=input.tilt;document.getElementById('slope').dispatchEvent(new Event('input'));return {result:document.getElementById('result').textContent};}})).catch(()=>{});}catch{}}
